<?php $productEscape = function ($value) {
    return html_escape(html_entity_decode((string) $value, ENT_QUOTES | ENT_HTML5, 'UTF-8'));
}; ?>
<section class="ui-page" aria-labelledby="product-details-title"><header class="ui-page-header"><div><p class="ui-eyebrow">PRODUTO #<?= (int) $result->idProdutos ?></p><h1 id="product-details-title"><?= $productEscape($result->descricao) ?></h1><p>Dados do produto e posição atual do estoque.</p></div><div class="ui-row-actions"><?php if ($this->permission->checkPermission($this->session->userdata('permissao'), 'eProduto')) { ?><a class="ui-button ui-button-primary" href="<?= site_url('produtos/editar/' . (int) $result->idProdutos) ?>">Editar produto</a><?php } ?><a class="ui-button" href="<?= site_url('produtos') ?>">Voltar aos produtos</a></div></header>
<div class="ui-card"><h2>Identificação e valores</h2><dl class="ui-detail-grid"><div><dt>Código de barras</dt><dd><?= $productEscape($result->codDeBarra ?: 'Não informado') ?></dd></div><div><dt>Unidade</dt><dd><?= $productEscape($result->unidade) ?></dd></div><div><dt>Preço de compra</dt><dd>R$ <?= $productEscape(number_format((float) $result->precoCompra, 2, ',', '.')) ?></dd></div><div><dt>Preço de venda</dt><dd>R$ <?= $productEscape(number_format((float) $result->precoVenda, 2, ',', '.')) ?></dd></div></dl></div>
<div class="ui-card ui-card-following"><h2>Estoque e movimentação</h2><dl class="ui-detail-grid"><div><dt>Estoque atual</dt><dd><?= $productEscape($result->estoque) ?> <?= $productEscape($result->unidade) ?></dd></div><div><dt>Estoque mínimo</dt><dd><?= $productEscape($result->estoqueMinimo) ?> <?= $productEscape($result->unidade) ?></dd></div><div><dt>Entrada permitida</dt><dd><?= (int) $result->entrada === 1 ? 'Sim' : 'Não' ?></dd></div><div><dt>Saída permitida</dt><dd><?= (int) $result->saida === 1 ? 'Sim' : 'Não' ?></dd></div></dl></div></section>
